const terminalServers = [
  {
    id: server.id,
    hostname: server.hostname,
    connect: server.dedicatedIp
      ? `ssh root@${server.dedicatedIp.address}`
      : `ssh -p ${server.sshPort ?? 22} root@${publicIp || "YOUR_SERVER_IP"}`,
  },
];

// SFTP/SSH connection details: dedicated-IP servers connect to their own IP on
