245	/**
246	 * Connect to the game-server VM (host/port derived exactly like the file manager,
247	 * user "root", password `rootPassword`), run `fn`, and always close the session.
248	 */
249	function withSsh<T>(server: SshServer, fn: (conn: Client, sftp: SFTPWrapper) => Promise<T>): Promise<T> {
250	  return new Promise((resolve, reject) => {
251	    const target = connectionTarget(server as any);
252	    if (!target) {
253	      reject(new Error("server is not reachable yet — connection details are pending"));
254	      return;
255	    }
256	    const password = serverRootPassword(server);
257	    if (!password) {
258	      reject(new Error("server has no root password set"));
259	      return;
260	    }
261	
262	    const conn = new Client();
263	    let settled = false;
264	    const finish = (err: Error | null, val?: T) => {
265	      if (settled) return;
266	      settled = true;
267	      try {
268	        conn.end();
269	      } catch {
270	        /* best-effort */
271	      }
272	      if (err) reject(err);
273	      else resolve(val as T);
274	    };
275	
276	    conn.on("ready", () => {
277	      conn.sftp((err, sftp) => {
278	        if (err) return finish(err);
279	        fn(conn, sftp).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
280	      });
281	    });
282	    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
283	    conn.connect({
284	      host: target.host,
285	      port: target.port,
286	      username: "root",
287	      password,
288	      readyTimeout: CONNECT_TIMEOUT_MS,
289	    });
290	  });
291	}
