293	/** Read a remote text file, or null if it does not exist. */
294	function sftpRead(sftp: SFTPWrapper, path: string): Promise<string | null> {
295	  return new Promise((resolve, reject) => {
296	    sftp.readFile(path, (err, data) => {
297	      if (err) {
298	        // ENOENT / no such file → null; anything else is a real error.
299	        const code = (err as NodeJS.ErrnoException).code;
300	        if (code === "ENOENT" || code === "No such file" || /no such file/i.test(err.message)) {
301	          return resolve(null);
302	        }
303	        return reject(err);
304	      }
305	      resolve(data.toString("utf8"));
306	    });
307	  });
308	}
