310	/** Write a remote text file (overwrites). */
311	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
312	  return new Promise((resolve, reject) => {
313	    sftp.writeFile(path, Buffer.from(content, "utf8"), (err) => (err ? reject(err) : resolve()));
314	  });
315	}
