317	/** Run a remote shell command; resolves with stdout/stderr/exit-code (never rejects on non-zero). */
318	function execRemote(conn: Client, cmd: string): Promise<{ code: number; stdout: string; stderr: string }> {
319	  return new Promise((resolve, reject) => {
320	    conn.exec(cmd, (err, stream: ClientChannel) => {
321	      if (err) return reject(err);
322	      let stdout = "";
323	      let stderr = "";
324	      const timer = setTimeout(() => {
325	        try {
326	          stream.close();
327	        } catch {
328	          /* ignore */
329	        }
330	      }, EXEC_TIMEOUT_MS);
331	      stream
332	        .on("close", (code: number) => {
333	          clearTimeout(timer);
334	          resolve({ code: code ?? 0, stdout, stderr });
335	        })
336	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
337	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
338	    });
339	  });
340	}
