342	/**
343	 * Locate the first existing path: try explicit candidates via `test -f`, then a
344	 * bounded `find` over `findRoots` for `findName`. Returns the path or null.
345	 * Non-destructive — only reads.
346	 */
347	async function remoteLocate(
348	  conn: Client,
349	  candidates: string[],
350	  findRoots: string[],
351	  findName: string
352	): Promise<string | null> {
353	  const testExpr = candidates.map((p) => `if [ -f '${shq(p)}' ]; then echo '${shq(p)}'; exit 0; fi;`).join(" ");
354	  const findExpr = findRoots.length
355	    ? `for r in ${findRoots.map((r) => `'${shq(r)}'`).join(" ")}; do [ -d "$r" ] && find "$r" -maxdepth 6 -type f -name '${shq(findName)}' 2>/dev/null | head -1; done | head -1`
356	    : "true";
357	  const { stdout } = await execRemote(conn, `${testExpr} ${findExpr}`);
358	  const hit = stdout.split(/\r?\n/).map((s) => s.trim()).find((s) => s.length > 0);
359	  return hit ?? null;
360	}
361	
362	/** Escape a value for single-quoted shell use. */
363	function shq(s: string): string {
364	  return s.replace(/'/g, "'\\''");
365	}
