367	/**
368	 * The systemd unit that supervises this family's game container, or null if the
369	 * guest has none.
370	 *
371	 * Every game family's setup script is rewritten at PROVISION time by
372	 * worker/index.ts's `wrapDockerGameService()` into `docker create` plus a
373	 * `<hint>.service` unit (`ExecStart=docker start -a <container>`,
374	 * `Restart=always`, `RestartSec=5`) — and that wrapper deliberately STRIPS
375	 * docker's own `--restart` policy, in its own words because "leaving both in
376	 * place makes the two supervisors fight over a crash-looping process". So on
377	 * every game server this platform provisions, systemd — not docker — owns the
378	 * container's lifecycle, and any apply path that stops or recreates a container
379	 * MUST go through it.
380	 *
381	 * Returns null when no unit resolves (a server provisioned before that wrapper
382	 * shipped, or a setup script that didn't match its `docker run -d --name X`
383	 * shape). There, docker's own restart policy is the only supervisor there is
384	 * and has to be preserved rather than replaced.
385	 *
386	 * The hints come from `lib/game-control.ts`'s per-family `controlSpec` — the
387	 * same list `worker/game-control.ts`'s power buttons resolve against, and the
388	 * same list `wrapDockerGameService` names the unit from ([0]) — so this can
389	 * never drift from the unit that actually got installed.
390	 */
391	async function resolveGameUnit(conn: Client, family: string): Promise<string | null> {
392	  const hints = controlSpec(family)?.serviceHints ?? [];
393	  if (!hints.length) return null;
394	  const probe = hints
395	    .map((h) => `systemctl cat '${shq(h)}.service' >/dev/null 2>&1 && { echo '${shq(h)}.service'; exit 0; };`)
396	    .join(" ");
397	  const { stdout } = await execRemote(conn, probe);
398	  const hit = stdout
399	    .split(/\r?\n/)
400	    .map((s) => s.trim())
401	    .find((s) => s.endsWith(".service"));
402	  return hit ?? null;
403	}
