428	// key=value file helpers (server.properties)
429	// ---------------------------------------------------------------------------
430	
431	/** Update `key=value` lines in place, preserving comments/unknown lines; append missing keys. */
432	function updateKeyValue(content: string, updates: Record<string, string>): string {
433	  const lines = content.split(/\r?\n/);
434	  const seen = new Set<string>();
435	  for (let i = 0; i < lines.length; i++) {
436	    const trimmed = lines[i].trim();
437	    if (!trimmed || trimmed.startsWith("#") || trimmed.startsWith("!")) continue;
438	    const eq = lines[i].indexOf("=");
439	    if (eq < 0) continue;
440	    const key = lines[i].slice(0, eq).trim();
441	    if (Object.prototype.hasOwnProperty.call(updates, key)) {
442	      lines[i] = `${key}=${updates[key]}`;
443	      seen.add(key);
444	    }
445	  }
446	  for (const k of Object.keys(updates)) {
447	    if (!seen.has(k)) lines.push(`${k}=${updates[k]}`);
448	  }
449	  return lines.join("\n");
450	}
451	
452	/** Read a `key=value` file into a map (comments/blank lines ignored). */
453	function parseKeyValue(content: string): Record<string, string> {
454	  const out: Record<string, string> = {};
455	  for (const line of content.split(/\r?\n/)) {
456	    const t = line.trim();
457	    if (!t || t.startsWith("#") || t.startsWith("!")) continue;
458	    const eq = line.indexOf("=");
459	    if (eq < 0) continue;
460	    out[line.slice(0, eq).trim()] = line.slice(eq + 1).trim();
461	  }
462	  return out;
463	}
