468	
469	/** Update `key value` (whitespace-separated) lines in place; append missing keys. */
470	function updateConvars(content: string, updates: Record<string, string>): string {
471	  const lines = content.split(/\r?\n/);
472	  const seen = new Set<string>();
473	  for (let i = 0; i < lines.length; i++) {
474	    const t = lines[i].trim();
475	    if (!t || t.startsWith("//") || t.startsWith("#")) continue;
476	    const sp = t.search(/\s/);
477	    const key = sp < 0 ? t : t.slice(0, sp);
478	    if (Object.prototype.hasOwnProperty.call(updates, key)) {
479	      lines[i] = `${key} ${updates[key]}`;
480	      seen.add(key);
481	    }
482	  }
483	  for (const k of Object.keys(updates)) {
484	    if (!seen.has(k)) lines.push(`${k} ${updates[k]}`);
485	  }
486	  return lines.join("\n");
487	}
