495	
496	/**
497	 * Read a container's current environment as a map.
498	 *
499	 * Recreating a container means re-supplying its WHOLE environment, not just the
500	 * keys being changed: the images this is used for get most of their defaults
501	 * from their own Dockerfile `ENV`s, and dropping those would silently reset
502	 * settings the customer never touched. `PATH` is excluded — the image always
503	 * injects a correct one, and carrying ours over would be wrong.
504	 */
505	async function readContainerEnv(conn: Client, container: string): Promise<Map<string, string> | null> {
506	  const inspect = await execRemote(conn, `docker inspect ${container} --format '{{json .Config.Env}}'`);
507	  if (inspect.code !== 0) return null;
508	  let envArr: string[];
509	  try {
510	    envArr = JSON.parse(inspect.stdout.trim());
511	  } catch {
512	    return null;
513	  }
514	  const envMap = new Map<string, string>();
515	  for (const entry of envArr) {
516	    const idx = entry.indexOf("=");
517	    if (idx < 0) continue;
518	    envMap.set(entry.slice(0, idx), entry.slice(idx + 1));
519	  }
520	  envMap.delete("PATH");
521	  return envMap;
522	}
523	
524	/** The exact image reference (repo:tag) a running container was created from. */
525	async function readContainerImage(conn: Client, container: string): Promise<string | null> {
526	  const res = await execRemote(conn, `docker inspect ${container} --format '{{.Config.Image}}'`);
527	  if (res.code !== 0) return null;
528	  const image = res.stdout.trim();
529	  return image || null;
530	}
