616	// Minecraft → server.properties (key=value), plus VERSION → container recreate
617	// ---------------------------------------------------------------------------
618	
619	const MINECRAFT_CONTAINER = "mc";
620	/**
621	 * Must track prisma/catalog.ts's minecraft template image tag exactly — see
622	 * that file's own comment on why `:java21` (not bare `:latest`) is required
623	 * for the platform's pinned default VERSION to actually run on a matching
624	 * Java runtime. A version-only settings change recreates the container from
625	 * THIS constant, so drifting the two out of sync would silently reintroduce
626	 * the wrong-Java-version bug for anyone who edits their version in Settings.
627	 */
628	const MINECRAFT_IMAGE = "itzg/minecraft-server:java21";
629	/** Ports + volume exactly as prisma/catalog.ts's minecraft template provisions them. */
630	const MINECRAFT_RUN_FLAGS = "-p 25565:25565 -p 25575:25575 -v /opt/mc:/data --env-file /root/mc.env";
631	
632	async function applyMinecraft(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
633	  // TODO(paths): confirm the actual install dir/service name for the Minecraft
634	  // image. These candidates cover the common layouts; if none match we soft-fail
635	  // rather than create a stray server.properties in the wrong place.
636	  const path = await remoteLocate(
637	    conn,
638	    [
639	      "/opt/minecraft/server.properties",
640	      "/srv/minecraft/server.properties",
641	      "/home/minecraft/server.properties",
642	      "/minecraft/server.properties",
643	      "/root/minecraft/server.properties",
644	    ],
645	    ["/opt", "/srv", "/home"],
646	    "server.properties"
647	  );
648	  if (!path) {
649	    return { ok: false, applied: [], notes: ["Could not locate server.properties — nothing was changed (restart/redeploy needed once the config path is known)."] };
650	  }
651	
652	  const existing = await sftpRead(sftp, path);
653	  if (existing == null) {
654	    return { ok: false, applied: [], notes: [`server.properties disappeared at ${path} — nothing was changed.`] };
655	  }
656	
657	  // server.properties keys map 1:1 to the schema field keys. VERSION is a
658	  // docker env var, not a server.properties key — it's handled separately
659	  // below via container recreate, not written to this file.
660	  const updates: Record<string, string> = {};
661	  for (const [key, val] of Object.entries(v)) {
662	    if (key === "VERSION") continue;
663	    updates[key] = typeof val === "boolean" ? bool(val) : String(val);
664	  }
665	  const next = updateKeyValue(existing, updates);
666	  await sftpWrite(sftp, path, next);
667	
668	  const applied: string[] = [`Wrote ${Object.keys(updates).length} setting(s) to ${path}.`];
669	  const notes: string[] = [];
670	
671	  // VERSION: itzg's image defaults to tracking Mojang's newest release on every
672	  // container restart unless VERSION is pinned (see prisma/catalog.ts's own
673	  // comment on this field for the live incident that found it). Also checks
674	  // the running image tag against MINECRAFT_IMAGE: a server provisioned before
675	  // the :java21 image tag existed is still on the bare (wrong-Java) image even
676	  // once VERSION itself is correctly pinned — found live 2026-09-06 on the
677	  // very Cobblemon server this field was built for, where VERSION pinned
678	  // clean but the container kept running the stale image's bundled JDK 25.
679	  // Only recreates when either actually differs from what's running, so an
680	  // ordinary gamemode/difficulty change never pays for a full container
681	  // recreate — same reasoning as `applyGameVariant`'s own no-op guard.
682	  const desiredVersion = v["VERSION"] != null ? String(v["VERSION"]) : null;
683	  if (desiredVersion) {
684	    const envMap = await readContainerEnv(conn, MINECRAFT_CONTAINER);
685	    const currentVersion = envMap?.get("VERSION") ?? null;
686	    const currentImage = await readContainerImage(conn, MINECRAFT_CONTAINER);
687	    const imageStale = currentImage !== null && currentImage !== MINECRAFT_IMAGE;
688	    if (envMap && (currentVersion !== desiredVersion || imageStale)) {
689	      envMap.set("VERSION", desiredVersion);
690	      envMap.delete("JAVA_VERSION"); // stale, baked in by whatever image created this container — let the new image set its own
691	      await writeEnvFile(conn, sftp, "/root/mc.env", envMap);
692	      const res = await recreateGameContainer(conn, {
693	        family: "minecraft",
694	        container: MINECRAFT_CONTAINER,
695	        runFlags: MINECRAFT_RUN_FLAGS,
696	        image: MINECRAFT_IMAGE,
697	      });
698	      if (!res.ok) {
699	        notes.push(`Wrote settings, but pinning the Minecraft version failed: ${res.note}`);
700	      } else {
701	        const parts: string[] = [];
702	        if (currentVersion !== desiredVersion) {
703	          parts.push(
704	            currentVersion
705	              ? `pinned Minecraft version to ${desiredVersion} (was ${currentVersion})`
706	              : `pinned Minecraft version to ${desiredVersion} (previously untracked — following Mojang's newest release on every restart)`
707	          );
708	        }
709	        if (imageStale) parts.push(`updated the server image to run the correct Java runtime for this version (was ${currentImage})`);
710	        const summary = parts.join(" and ");
711	        applied.push(`${summary.charAt(0).toUpperCase()}${summary.slice(1)}, and restarted the server.`);
712	      }
713	    }
714	  }
715	
716	  // Best-effort live push via RCON for the live-editable fields; otherwise note a
717	  // restart. Wrapped so RCON problems never fail the apply.
718	  try {
719	    await tryMinecraftRcon(conn, next, v, notes);
720	  } catch (e) {
721	    notes.push("RCON push skipped (unavailable). A restart is required for changes to take effect.");
722	    console.error("[game-config] minecraft rcon error", e);
723	  }
724	
725	  return {
726	    ok: true,
727	    applied,
728	    notes: notes.length ? notes : ["Restart the server for deploy-time settings (hardcore, online-mode) to take effect."],
729	  };
730	}
731	
732	/**
733	 * Best-effort Minecraft RCON push. Reads rcon config from the (updated)
734	 * server.properties; if RCON is enabled, a password is set, and `mcrcon` exists
735	 * on the box, pushes the live-editable settings. Anything missing → note a restart.
736	 */
737	async function tryMinecraftRcon(conn: Client, props: string, v: Values, notes: string[]): Promise<void> {
738	  const kv = parseKeyValue(props);
739	  const enabled = kv["enable-rcon"] === "true";
740	  const password = kv["rcon.password"] ?? "";
741	  // `rcon.port` is read out of the CUSTOMER'S OWN server.properties, on the
742	  // customer's own VM — an attacker-controlled string in every sense, and one
743	  // this platform never wrote. Only a TCP port number can ever be legitimate, so
744	  // anything that is not one is discarded rather than escaped. `shq` and the
745	  // quoting below are the second and third lines of defence; this is the first,
746	  // and it is the only one that does not depend on getting quoting right.
747	  const port = rconPort(kv["rcon.port"]);
748	  if (!enabled || !password) {
749	    notes.push("RCON is not enabled — restart the server to apply the new settings live.");
750	    return;
751	  }
752	  const which = await execRemote(conn, "command -v mcrcon || true");
753	  if (!which.stdout.trim()) {
754	    notes.push("RCON is enabled but `mcrcon` is not installed — restart to apply live.");
755	    return;
756	  }
757	
758	  // A conservative set of safe live commands. TODO(rcon): expand once the exact
759	  // runtime command set is verified for the target Minecraft build.
760	  const cmds: string[] = [];
761	  if (v["difficulty"] != null) cmds.push(`difficulty ${String(v["difficulty"])}`);
762	  if (v["white-list"] != null) cmds.push(`whitelist ${bool(v["white-list"]) === "true" ? "on" : "off"}`);
763	  if (v["pvp"] != null || v["max-players"] != null || v["motd"] != null) cmds.push("reload");
764	  if (cmds.length === 0) return;
765	
766	  const quoted = cmds.map((c) => `'${shq(c)}'`).join(" ");
767	  // EVERY interpolation is inside single quotes. `shq` escapes a value for use
768	  // INSIDE a single-quoted string — it is not a quoter, and a bare `${shq(x)}`
769	  // is simply an unquoted, word-splitting, metacharacter-honouring shell
770	  // argument. `-P` was written that way, so `rcon.port=1; curl … | sh` in the
771	  // customer's own server.properties ran as root on the hypervisor's SSH client
772	  // target with no further steps required.
773	  //
774	  // The `|| true` that used to end this line is gone. It forced exit 0, so the
775	  // `res.code === 0` test below was a constant and this function reported
776	  // "Pushed live settings via RCON." whether mcrcon worked, refused the
777	  // password, or was never reached. `execRemote` resolves with the real exit
778	  // code rather than rejecting, so nothing here can throw on a non-zero status —
779	  // the note just becomes true.
780	  const res = await execRemote(
781	    conn,
782	    `mcrcon -H 127.0.0.1 -P '${shq(port)}' -p '${shq(password)}' ${quoted} 2>&1`
783	  );
784	  notes.push(res.code === 0 ? "Pushed live settings via RCON." : "RCON push attempted (some settings may need a restart).");
785	}
