787	/**
788	 * The RCON port to talk to, from an untrusted `rcon.port` value.
789	 *
790	 * Accepts only a bare 1–65535 decimal; anything else (empty, non-numeric, out of
791	 * range, or carrying a shell payload) falls back to Minecraft's default 25575.
792	 * Returns a string because it is interpolated into a command line, and returning
793	 * the parsed digits — never the caller's original text — is what makes the value
794	 * safe by construction rather than by escaping.
795	 */
796	function rconPort(raw: string | undefined): string {
797	  const n = Number(String(raw ?? "").trim());
798	  if (!Number.isInteger(n) || n < 1 || n > 65535) return "25575";
799	  return String(n);
800	}
