805	
806	const RUST_CONTAINER = "rust";
807	const RUST_IMAGE = "didstopia/rust-server";
808	/** Ports + volume exactly as prisma/catalog.ts's Rust template provisions them. */
809	const RUST_RUN_FLAGS = "-p 28015:28015/udp -p 28016:28016 -v /opt/rust:/steamcmd/rust --env-file /root/rust.env";
810	
811	/**
812	 * Schema field key → the `didstopia/rust-server` env var that sets it.
813	 *
814	 * Read directly out of the image's own `/app/start.sh` on a real running
815	 * container (2026-09-06), not guessed — it builds the launch line with
816	 * `add_argument_pair ARGUMENTS "+server.hostname" "RUST_SERVER_NAME"` and
817	 * friends. `pve` has no env var of its own and goes through
818	 * `RUST_SERVER_STARTUP_ARGUMENTS` instead (see below).
819	 */
820	const RUST_ENV_MAP: Record<string, string> = {
821	  hostname: "RUST_SERVER_NAME",
822	  maxplayers: "RUST_SERVER_MAXPLAYERS",
823	  worldsize: "RUST_SERVER_WORLDSIZE",
824	  seed: "RUST_SERVER_SEED",
825	};
