827	/** Replace `<flag> <value>` in an argument string, or append the pair if absent. */
828	function upsertArg(args: string, flag: string, value: string): string {
829	  const esc = flag.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
830	  const re = new RegExp(`(^|\\s)${esc}\\s+\\S+`);
831	  return re.test(args) ? args.replace(re, `$1${flag} ${value}`) : `${args} ${flag} ${value}`.trim();
832	}
833	
834	/** Replace `+convar <value>` in a Rust startup-argument string, or append it. */
835	function upsertConvarArg(args: string, convar: string, value: string): string {
836	  return upsertArg(args, `+${convar}`, value);
837	}
