866	  const envMap = await readContainerEnv(conn, RUST_CONTAINER);
867	  if (!envMap) {
868	    return { ok: false, applied: [], notes: [`Could not find the "${RUST_CONTAINER}" container — nothing was changed.`] };
869	  }
870	
871	  const applied: string[] = [];
872	  const notes: string[] = [];
873	  for (const [key, val] of Object.entries(v)) {
874	    if (val == null) continue;
875	    const env = RUST_ENV_MAP[key];
876	    if (env) {
877	      envMap.set(env, String(val));
878	      applied.push(key);
879	    } else if (key === "pve") {
880	      // No RUST_SERVER_PVE exists. start.sh passes RUST_SERVER_STARTUP_ARGUMENTS
881	      // through verbatim ahead of the generated pairs, so it is the image's own
882	      // escape hatch for any convar it has no variable for.
883	      const args = envMap.get("RUST_SERVER_STARTUP_ARGUMENTS") ?? "-batchmode -load -nographics +server.secure 1";
884	      envMap.set("RUST_SERVER_STARTUP_ARGUMENTS", upsertConvarArg(args, "server.pve", bool(val)));
885	      applied.push(key);
886	    }
887	  }
888	  if (applied.length === 0) {
889	    return { ok: true, applied: [], notes: ["No changes to apply."] };
890	  }
891	
892	  await writeEnvFile(conn, sftp, "/root/rust.env", envMap);
893	
894	  const res = await recreateGameContainer(conn, {
895	    family: "rust",
896	    container: RUST_CONTAINER,
897	    runFlags: RUST_RUN_FLAGS,
898	    image: RUST_IMAGE,
899	  });
900	  if (!res.ok) return { ok: false, applied: [], notes: [res.note] };
