902	  if (v["worldsize"] != null || v["seed"] != null) {
903	    notes.push("World size / seed only take effect on a fresh map — the existing save is kept until the next wipe.");
904	  }
905	  notes.push(
906	    "Rust reloads its whole map on restart, so your server will be offline for several minutes before players can rejoin."
907	  );
908	
909	  return { ok: true, applied: [`Applied ${applied.length} setting(s): ${applied.join(", ")}.`], notes };
910	}
