1099	    },
1100	  },
1101	  "player-caps": { env: "PLAYERS", format: (v) => String(v) },
1102	  "pal-box-import": { env: "ALLOW_GLOBAL_PALBOX_IMPORT", format: (v) => (bool(v) === "true" ? "True" : "False") },
1103	  "pal-box-export": { env: "ALLOW_GLOBAL_PALBOX_EXPORT", format: (v) => (bool(v) === "true" ? "True" : "False") },
